import test from 'node:test';
import assert from 'node:assert/strict';
import {readFileSync} from 'node:fs';
import {createHash} from 'node:crypto';
import * as c from '../src/index.js';
const bytes=readFileSync(new URL('../integration/fixtures/curriculum-v7-365.json',import.meta.url));
const data=JSON.parse(bytes);const report=c.inspectCurriculum(data);const copy=x=>structuredClone(x);
const doneFor=unitId=>data.lessons.filter(lesson=>lesson.unit_id===unitId).map(lesson=>lesson.id);
const build=unitId=>c.buildCurriculumQuickReview(data,unitId,{completedLessonIds:doneFor(unitId)});
const begin=unitId=>c.transitionChapterReview(c.createChapterReviewSession(build(unitId).plan,{sessionId:`v7-${unitId}`,profileId:'synthetic-profile'}),{type:'begin'});
const answer=s=>c.transitionChapterReview(s,{type:'answer',questionId:s.queue[s.cursor].id,response:s.queue[s.cursor].correctOptionId,at:'2026-11-08T02:00:00.000Z',timeZone:'Asia/Ho_Chi_Minh',durationMs:1000});
test('final v7 has all sixty authored chapter reviews without adding numbered lessons',()=>{assert.equal(report.units,60);assert.equal(report.lessons,365);assert.equal(report.vocabularyCards+report.languageTargets,320);assert.equal(report.quickReviews.length,60);assert.equal(report.quickReviews.reduce((sum,r)=>sum+r.questionCount,0),180);assert.equal(report.interactiveChallenges.length,16);assert.equal(Math.max(...data.lessons.map(lesson=>lesson.day)),365);});
test('every v7 chapter review runs, retains source IDs and round-trips its snapshot',()=>{for(const review of report.quickReviews){let state=begin(review.unitId);const ids=state.plan.source.questionIds;for(let i=0;i<3;i++){state=answer(state);if(i===1)state=c.restoreCurriculumReviewSnapshot(c.exportChapterReviewSnapshot(state),data,state.profileId);state=c.transitionChapterReview(state,{type:'next'});}assert.equal(state.status,'completed');assert.equal(state.result.firstPassCorrect,3);assert.equal(state.events.length,0);assert.deepEqual(c.curriculumQuestionOutcomes(state).map(result=>result.questionId),ids);}});
test('all 132 added provenance records are preserved and never become word-mastery events',()=>{let total=0;for(const review of report.quickReviews){const plan=build(review.unitId).plan;const sourceLesson=data.lessons.find(lesson=>lesson.id===review.lessonId);const sourceReview=sourceLesson.activities.find(a=>a.id===review.activityId);for(const question of plan.questions){const source=sourceReview.questions.find(q=>q.id===question.id);if(source.source_references){total++;assert.deepEqual(question.sourceReferences,source.source_references);assert.equal(question.masteryPolicy,'practice_only_do_not_infer_word_mastery_from_broad_context');assert.equal(question.cardId,null);}assert.equal(question.prompt,source.prompt);}}assert.equal(total,132);});
test('story recap preserves self-contained reading context exactly',()=>{const plan=build('stories').plan;assert.ok(plan.questions[0].prompt.includes('Linh felt sad. Then Dad showed her a photo of the castle. Linh smiled.'));assert.deepEqual(plan.questions[0].sourceReferences.source_story_ids,['beach-day']);assert.equal(plan.questions[0].assessmentScope,'question');});
test('legacy memory tips and support glossary reach the focus view',()=>{const plan=build('colors').plan;const state=c.createChapterReviewSession(plan,{sessionId:'focus-v7',profileId:'p'});const view=c.chapterQuestionView(state);assert.equal(view.memoryTip.en,'It is blue. I like blue.');assert.ok(view.supportGlossary.some(pair=>pair[0]==='like'));});
test('mixed English/Vietnamese options are not mislabeled as English-only',()=>{const plan=build('colors').plan;assert.equal(plan.questions[1].language,null);assert.equal(plan.questions[1].promptLanguage,'mixed_en_vi');assert.ok(plan.questions[1].options.some(option=>option.label.includes('Nhân vật')));});
test('all sixteen v7 structured challenges grade full keys and leave shortened tasks observed',()=>{const challenges=data.lessons.flatMap(lesson=>lesson.activities.filter(a=>a.type==='interactive_challenge'));assert.equal(challenges.length,16);for(const challenge of challenges){assert.equal(c.gradeInteractiveChallenge(challenge,challenge.answer).correct,true);assert.equal(c.gradeInteractiveChallenge(challenge,null,{shortened:true}).autoGraded,false);}});
test('four-event source tasks on354 and360 remain four events, not hard-coded triples',()=>{for(const day of [354,360]){const lesson=data.lessons.find(l=>l.day===day);const task=lesson.activities.find(a=>a.type==='order_sentences');assert.equal(task.items.length,4);assert.equal(task.answer_item_ids.length,4);assert.deepEqual([...task.answer_item_ids].sort(),task.items.map(item=>item.id).sort());}});
test('five optional post-course review cards are not imported as extra lessons',()=>{const post=JSON.parse(readFileSync(new URL('../integration/fixtures/post-course-review-v7.json',import.meta.url)));assert.equal(post.cards.length,5);assert.ok(post.cards.every(card=>card.status==='optional_follow_on_review_not_numbered_lesson'&&card.scoring==='adult_observation'&&card.requires_microphone===false));assert.equal(c.adaptCurriculumCatalog(data).catalog.lessons.length,365);});
test('invalid provenance references and future source lessons fail clearly',()=>{const bad=copy(data);const q=bad.lessons.find(l=>l.day===6).activities.find(a=>a.type==='quick_review').questions[0];q.source_references.source_vocabulary_ids=['missing'];assert.throws(()=>c.inspectCurriculum(bad),/question source vocabulary/);q.source_references.source_vocabulary_ids=['bird'];q.source_references.source_lesson_ids=['day-365'];assert.throws(()=>c.inspectCurriculum(bad),/future lesson/);});
test('provenance cannot request automatic per-word mastery',()=>{const bad=copy(data);bad.lessons.find(l=>l.day===6).activities.find(a=>a.type==='quick_review').questions[0].mastery_policy='mark-all-words-mastered';assert.throws(()=>c.inspectCurriculum(bad),/word mastery/);});
test('v7 data remains byte-identical to the finalized source checkpoint',()=>{const manifest=JSON.parse(readFileSync(new URL('../integration/SOURCE-v7.json',import.meta.url)));assert.equal(createHash('sha256').update(bytes).digest('hex'),manifest.files.find(file=>file.file==='curriculum-v7-365.json').sha256);const before=JSON.stringify(data);c.adaptCurriculumCatalog(data);assert.equal(JSON.stringify(data),before);});
